3	namespace App\Jobs;
4	
5	use Carbon\Carbon;
6	use Strava\API\Client;
7	use App\Models\User;
8	use App\Models\Activity;
9	use Illuminate\Bus\Queueable;
10	use App\Services\Api\AuthService;
11	use App\Services\Rest\StravaRest;
12	use GuzzleHttp\Client as Adapter;
13	use Illuminate\Queue\SerializesModels;
14	use Illuminate\Queue\InteractsWithQueue;
15	use Illuminate\Contracts\Queue\ShouldQueue;
16	use Illuminate\Foundation\Bus\Dispatchable;
17	use Illuminate\Queue\Middleware\RateLimited;
18	
19	class SyncUserActivities implements ShouldQueue
20	{
21	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
22	
23	    public $tries = 5;
24	    public $maxExceptions = 3;
25	
26	    public function __construct(
27	        protected User $user,
28	        protected int $days = 30,
29	        protected int $maxPages = 5,
30	    ) {}
31	
32	    public function handle(Adapter $adapter, AuthService $authService)
33	    {
34	        if (!$this->user->isConnected()) {
35	            return;
36	        }
37	
38	        $token = $authService->checkAndRefreshTokenForUser($this->user);
39	
40	        $service = new StravaRest($token, $adapter);
41	        $apiClient = new Client($service);
42	
43	        $after = Carbon::now()->subDays($this->days)->startOfDay()->timestamp;
44	        $page = 1;
45	        $synced = 0;
46	
47	        do {
48	            $activities = $apiClient->getAthleteActivities(
49	                before: null,
50	                after: $after,
51	                page: $page,
52	                per_page: 200,
53	            );
54	
55	            if (empty($activities)) {
56	                break;
57	            }
58	
59	            foreach ($activities as $activityData) {
60	                Activity::firstOrCreate(
61	                    ['ext_id' => $activityData['id']],
62	                    array_merge(
63	                        ['user_id' => $this->user->id],
64	                        Activity::mapFromStrava($activityData),
65	                    ),
66	                );
67	                $synced++;
68	            }
69	
70	            $page++;
71	        } while (count($activities) === 200 && $page <= $this->maxPages);
72	    }
73	
74	    public function middleware(): array
75	    {
76	        return [new RateLimited('webhook_process')];
77	    }
78	}

